const ibEl = insp && insp.querySelector('.sm-body');
const mm   = $(cfg.minimap  || '.sm-mini canvas');
const mc   = mm && mm.getContext('2d');
const dlg  = $(cfg.dialog   || 'dialog.sm-dlg');
const qEl  = $(cfg.search   || '.sm-find input');

/* ── 状态 ────────────────────────────────────────────────────────── */
